{
  "avaliacoes": [
    {
      "id": "E03c3b0caaed0ac0f",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na condição de offloading, o sistema formado por navio cisterna e navio aliviador é submetido simultaneamente a ventos, correntes e ondas com magnitudes e direções distintas, o que compõe o contexto técnico da operação.",
          "trechos": [
            "E03c3b0caaed0ac0f:0:696"
          ],
          "condicoes": [
            "Aplicável ao cenário de transferência oceânica de óleo entre FPSO de aproamento fixo e navio aliviador com posicionamento dinâmico mencionado na fonte."
          ],
          "limites": [
            "O trecho não quantifica limites ambientais nem critérios de aceitação para prosseguir a operação.",
            "Não detalha como cada agente ambiental afeta bombas, válvulas ou sequência de tanques."
          ]
        },
        {
          "proposicao": "Durante operações de alívio, grandes variações de calado das embarcações modificam o agente ambiental predominante e, por consequência, a dinâmica do sistema flutuante.",
          "trechos": [
            "E03c3b0caaed0ac0f:696:1395"
          ],
          "condicoes": [
            "Associado ao desenvolvimento da operação de alívio do óleo."
          ],
          "limites": [
            "O trecho não explicita como essas variações de calado se relacionam ao gerenciamento de lastro, estabilidade ou controle de níveis.",
            "Não apresenta método de cálculo ou monitoramento."
          ]
        },
        {
          "proposicao": "Mesmo com aumento da capacidade propulsiva instalada nos navios, a fonte afirma que existem condições ambientais em que, devido às restrições dos modos e setores operacionais, o navio aliviador não consegue manter posição.",
          "trechos": [
            "E03c3b0caaed0ac0f:1395:2092"
          ],
          "condicoes": [
            "Contexto de operações de alívio em terminais oceânicos de aproamento fixo."
          ],
          "limites": [
            "O trecho não identifica quais condições ambientais são essas porque os valores não aparecem.",
            "Não informa resposta operacional específica além da limitação de manutenção de posição."
          ]
        }
      ]
    },
    {
      "id": "E3530141218fd6dd0",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na sequência descrita da operação, o lançamento do sistema de amarração ocorre com auxílio de lancha quando o navio aliviador está a aproximadamente 1000 metros do FPSO e com velocidade máxima de 1,5 nós.",
          "trechos": [
            "E3530141218fd6dd0:0:698"
          ],
          "condicoes": [
            "Válido para a sequência operacional descrita na fonte."
          ],
          "limites": [
            "Os valores apresentados pertencem à descrição do procedimento dessa fonte e não são tratados como requisito universal.",
            "O trecho não informa critérios de exceção, tolerâncias ou condições ambientais associadas."
          ]
        },
        {
          "proposicao": "Após a conexão do mangote, a linha de transferência deve ser pressurizada antes do início da transferência, mantendo-se a válvula de transferência aberta e a válvula coletora do navio aliviador fechada para sustentar a pressão na linha.",
          "trechos": [
            "E3530141218fd6dd0:698:1397",
            "E3530141218fd6dd0:1397:2091"
          ],
          "condicoes": [
            "Aplicável à etapa posterior à conexão do mangote e anterior ao início da transferência."
          ],
          "limites": [
            "O trecho não fornece pressão-alvo, tempo de estabilização, critérios de aceitação ou intertravamentos.",
            "Não especifica instrumentos de medição nem responsabilidades por cada comando."
          ]
        },
        {
          "proposicao": "Quando o processo está começando ou terminando, as válvulas devem ser reguladas para vazão baixa, sendo essa condição associada no final da etapa à prevenção de transbordamento do tanque.",
          "trechos": [
            "E3530141218fd6dd0:1397:2091"
          ],
          "condicoes": [
            "Aplicável ao início e ao término da transferência de óleo cru do FPSO para o navio aliviador."
          ],
          "limites": [
            "O trecho não informa quais válvulas participam, nem define valores de vazão, pressão ou nível.",
            "Não identifica a sequência de tanques nem a lógica de controle do enchimento."
          ]
        }
      ]
    },
    {
      "id": "E54a65016439906fb",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A operação de transferência de óleo por offloading é apresentada como elemento fundamental da cadeia produtiva do escoamento com FPSO.",
          "trechos": [
            "E54a65016439906fb:0:688"
          ],
          "condicoes": [
            "No contexto de projetos de FPSO com armazenamento a bordo."
          ],
          "limites": [
            "A afirmação é geral e não detalha controles operacionais específicos de transferência, bombas ou válvulas."
          ]
        },
        {
          "proposicao": "Na condição de offloading, o conjunto navio-cisterna/navio-aliviador está sujeito a ventos, correnteza e ondas com magnitudes e direções distintas, e as variações de calado alteram a dinâmica do sistema flutuante.",
          "trechos": [
            "E54a65016439906fb:0:688"
          ],
          "condicoes": [
            "Aplicável às operações de alívio descritas na fonte."
          ],
          "limites": [
            "O trecho não apresenta limites ambientais, envelopes operacionais nem consequências quantitativas para estabilidade ou posicionamento.",
            "Não relaciona diretamente essa dinâmica à sequência de tanques."
          ]
        },
        {
          "proposicao": "A fonte menciona como frentes de desenvolvimento na Petrobras treinamento de capitães-de-manobra, simulador de apoio, definição de áreas de exclusão e setores de operação, e novas práticas operacionais para aproximação, amarração e permanência em tandem em terminais oceânicos.",
          "trechos": [
            "E54a65016439906fb:1385:2077",
            "E54a65016439906fb:2077:2362"
          ],
          "condicoes": [
            "No contexto de projetos e metodologias associados a operações em terminais oceânicos."
          ],
          "limites": [
            "O trecho não descreve o conteúdo técnico dessas práticas, nem comprova seus resultados operacionais.",
            "Não especifica como essas iniciativas se traduzem em procedimentos de controle de vazão, pressão ou níveis."
          ]
        }
      ]
    },
    {
      "id": "E81f378e923074656",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em FPSOs, condições marítimas adversas podem agitar excessivamente os fluidos nos vasos separadores da planta de processamento primário, perturbando a separação por remistura dos fluidos.",
          "trechos": [
            "E81f378e923074656:689:1380"
          ],
          "condicoes": [
            "Referido às instalações flutuantes de produção existentes e aos vasos separadores da planta de processamento primário."
          ],
          "limites": [
            "O trecho trata do processamento primário, não da etapa de offloading para navio aliviador.",
            "Não relaciona diretamente esse efeito a manobras de lastro ou sequência de tanques de carga."
          ]
        },
        {
          "proposicao": "A mesma agitação pode promover alarmes incorretos de nível dos fluidos e até ocasionar parada da produção.",
          "trechos": [
            "E81f378e923074656:689:1380"
          ],
          "condicoes": [
            "Sob condições marítimas adversas que afetem os equipamentos de separação."
          ],
          "limites": [
            "O trecho não especifica quais instrumentos de nível são afetados nem quais critérios levam ao shutdown.",
            "A consequência mencionada refere-se à produção, não necessariamente à transferência de carga."
          ]
        },
        {
          "proposicao": "A fonte sustenta que tecnologias ciclônicas podem minimizar perda de desempenho da separação e descontrole do nível de interface, por terem desempenho descrito como independente do movimento da embarcação.",
          "trechos": [
            "E81f378e923074656:1380:2073"
          ],
          "condicoes": [
            "No contexto de emprego de novas tecnologias ciclônicas em substituição parcial de equipamentos convencionais."
          ],
          "limites": [
            "Trata-se de explicação técnica e expectativa de desempenho, não de comprovação universal para qualquer instalação.",
            "Os valores numéricos da aceleração centrífuga estão apagados e não podem ser reconstruídos."
          ]
        }
      ]
    },
    {
      "id": "E846762f2e6e24795",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Na investigação do FPSO CDSM, não havia evidência de treinamento formal da equipe de marinha para procedimentos específicos de transferência de carga entre tanques, embora existissem registros de treinamentos em outros procedimentos de segurança operacional e formulários de verificação para offloading.",
          "trechos": [
            "E846762f2e6e24795:0:690",
            "E846762f2e6e24795:690:1390"
          ],
          "condicoes": [
            "Constatação restrita ao caso investigado do FPSO Cidade de São Mateus.",
            "Refere-se à equipe envolvida com transferência entre tanques, como bombeador, operadores de marinha e novo superintendente de marinha."
          ],
          "limites": [
            "O trecho não descreve o conteúdo técnico do procedimento de transferência entre tanques.",
            "O trecho não demonstra, por si só, como a ausência de treinamento afetou cada ação operacional específica."
          ]
        },
        {
          "proposicao": "A investigação registra que, na data do acidente, não havia controle implementado para assegurar manutenção da força de trabalho treinada nos procedimentos operacionais com impacto à segurança operacional, e essa falha foi enquadrada como descumprimento do item 3.3.4 do SGSO.",
          "trechos": [
            "E846762f2e6e24795:1390:2086"
          ],
          "condicoes": [
            "Conclusão formulada no relatório da ANP para o evento investigado."
          ],
          "limites": [
            "O trecho não reproduz o teor do item 3.3.4 do SGSO.",
            "A constatação normativa é vinculada ao caso e ao sistema de gestão analisado no relatório."
          ]
        },
        {
          "proposicao": "O controle do funcionamento da bomba de stripping era realizado por operador de marinha por meio de interface homem-máquina do sistema de transferência de carga, indicando integração entre operação de bomba e supervisão por sistema.",
          "trechos": [
            "E846762f2e6e24795:2086:2328"
          ],
          "condicoes": [
            "Descrição referente ao arranjo operacional observado no FPSO CDSM."
          ],
          "limites": [
            "O trecho não informa lógica de intertravamento, permissivos, alarmes, setpoints ou critérios de acionamento da bomba.",
            "Não há, nesse excerto, sequência operacional completa nem relação explícita com níveis ou pressões."
          ]
        }
      ]
    },
    {
      "id": "Eee3fc82ff7eadd8c",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": [
        {
          "proposicao": "A fonte traz predominantemente lista de siglas, sumário e menções genéricas a regulamentação e segurança operacional, sem desenvolver conteúdo técnico suficiente sobre bombas, válvulas, vazão, pressão, níveis, sequência de tanques, estabilidade ou coordenação entre equipes no recorte solicitado.",
          "trechos": [
